import React from 'react';
import { TextField, Box } from '@mui/material';
import { styled } from '@mui/material/styles';

const BlurTextField = styled(TextField)(({ theme }) => ({
  '& .MuiOutlinedInput-root': {
    backgroundColor: 'rgba(255, 255, 255, 0.1)',
    backdropFilter: 'blur(10px)',
    borderRadius: '8px',
    
    '&:hover': {
      backgroundColor: 'rgba(255, 255, 255, 0.15)',
    },
    
    '&.Mui-focused': {
      backgroundColor: 'rgba(255, 255, 255, 0.2)',
      
      '& .MuiOutlinedInput-notchedOutline': {
        borderColor: '#FF9800',
        borderWidth: '2px',
      },
    },
    
    '& .MuiOutlinedInput-input': {
      color: theme.palette.common.white,
      padding: '12px 14px',
    },
  },
  
  '& .MuiInputLabel-root': {
    color: 'rgba(255, 255, 255, 0.7)',
    
    '&.Mui-focused': {
      color: '#FF9800',
    },
  },
  
  '& .MuiOutlinedInput-notchedOutline': {
    borderColor: 'rgba(255, 255, 255, 0.3)',
    transition: 'all 0.3s ease',
  },
}));

// Alternative version with more pronounced blur effect
const GlassInputField = styled(TextField)(({ theme }) => ({
  '& .MuiOutlinedInput-root': {
    background: 'rgba(255, 255, 255, 0.1)',
    backdropFilter: 'blur(15px)',
    borderRadius: '12px',
    border: '1px solid rgba(255, 255, 255, 0.2)',
    transition: 'all 0.3s ease',
    
    '&:hover': {
      background: 'rgba(255, 255, 255, 0.15)',
      borderColor: 'rgba(255, 255, 255, 0.3)',
    },
    
    '&.Mui-focused': {
      background: 'rgba(255, 255, 255, 0.2)',
      borderColor: '#FF9800',
      boxShadow: '0 0 0 2px rgba(255, 152, 0, 0.2)',
      
      '& .MuiOutlinedInput-notchedOutline': {
        borderColor: '#FF9800',
        borderWidth: '0px', // Hide default outline since we're using border
      },
    },
  },
  
  '& .MuiInputLabel-root': {
    color: 'rgba(255, 255, 255, 0.7)',
    fontWeight: 500,
    
    '&.Mui-focused': {
      color: '#FF9800',
      fontWeight: 600,
    },
  },
  
  '& .MuiOutlinedInput-notchedOutline': {
    border: 'none', // Remove default border since we're using custom border
  },
  
  '& .MuiOutlinedInput-input': {
    color: '#ffffff',
    padding: '14px 16px',
    fontSize: '16px',
    
    '&::placeholder': {
      color: 'rgba(255, 255, 255, 0.5)',
    },
  },
}));

// Main component
const BasicInput = () => {
  return (
    <Box
      sx={{
        padding: '40px',
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        minHeight: '100vh',
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      {/* Version 1: Simple blur background */}
      <BlurTextField
        label="Blur Background Input"
        variant="outlined"
        fullWidth
        sx={{ maxWidth: '400px' }}
      />
      
      {/* Version 2: Glass morphism effect */}
      <GlassInputField
        label="Glass Effect Input"
        variant="outlined"
        placeholder="Type something..."
        fullWidth
        sx={{ maxWidth: '400px' }}
      />
      
      {/* Version 3: With different orange shades */}
      <TextField
        label="Custom Orange Focus"
        variant="outlined"
        fullWidth
        sx={{
          maxWidth: '400px',
          '& .MuiOutlinedInput-root': {
            backgroundColor: 'rgba(255, 255, 255, 0.08)',
            backdropFilter: 'blur(8px)',
            borderRadius: '8px',
            
            '&.Mui-focused': {
              backgroundColor: 'rgba(255, 255, 255, 0.12)',
              '& .MuiOutlinedInput-notchedOutline': {
                borderColor: '#FF6D00', // Darker orange
                borderWidth: '2px',
              },
            },
          },
          '& .MuiInputLabel-root.Mui-focused': {
            color: '#FF6D00',
          },
          '& .MuiOutlinedInput-input': {
            color: '#ffffff',
          },
        }}
      />
    </Box>
  );
};

export default BasicInput;
